#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Complex {
    re: i32,
    im: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Fixed machine epsilon as given in problem
    let epsilon = 2;

    // Check if all imaginary parts are "close to zero":
    // |im| <= tol * epsilon
    let all_close = arr.iter().all(|c| {
        let abs_im = if c.im < 0 { -c.im } else { c.im };
        abs_im <= tol * epsilon
    });

    if all_close {
        // Additionally, if all imaginary parts are exactly zero,
        // return the original array unchanged.
        let all_zero = arr.iter().all(|c| c.im == 0);
        if all_zero {
            // Already real, return the input unchanged
            return arr;
        }

        // Otherwise return array with imaginary parts zeroed,
        // preserving real parts exactly.
        arr.into_iter()
            .map(|c| Complex { re: c.re, im: 0 })
            .collect()
    } else {
        // Otherwise, return input array unchanged
        arr
    }
}